update_card_ai.beforeRequest:
if (!Array.isArray(request.body.idLabels) || request.body.idLabels.length === 0) delete request.body.idLabels;
var closed = String(inputs.closed ?? '').trim().toLowerCase();
if (closed === 'yes' || closed === 'true') request.body.closed = true;
if (closed === 'no' || closed === 'false') request.body.closed = false;
return request;

search_cards.beforeRequest:
var ids = inputs.board_ids ? JSON.parse(inputs.board_ids) : [];
if (ids && ids.length > 0) request.query.idBoards = ids.join(',');
var limit = Number(inputs.limit);
if (limit) request.query.cards_limit = String(limit);
else delete request.query.cards_limit;
return request;

search_members.beforeRequest:
if (inputs.only_org_members === 'true') request.query.onlyOrgMembers = 'true';
var limit = Number(inputs.limit);
if (limit) request.query.limit = String(limit);
else delete request.query.limit;
return request;

list_card_comments.beforeRequest:
var limit = Number(inputs.limit);
if (limit) request.query.limit = String(limit);
else delete request.query.limit;
return request;

list_board_labels.beforeRequest:
var limit = Number(inputs.limit);
if (limit) request.query.limit = String(limit);
else delete request.query.limit;
return request;

set_card_custom_field_value.beforeRequest:
var value = inputs.value ?? '';
var type = inputs.field_type;
if (type === 'text') request.body = {value: {text: value}};
else if (type === 'number') request.body = {value: {number: value}};
else if (type === 'date') request.body = {value: {date: value}};
else if (type === 'checkbox') {
  var flag = value.trim().toLowerCase();
  if (flag !== 'true' && flag !== 'false') throw new Error('Checkbox fields accept only "true" or "false", but received "' + value + '".');
  request.body = {value: {checked: flag === 'true'}};
}
else if (type === 'list') request.body = {idValue: value};
else throw new Error('Unsupported field type "' + type + '". Use text, number, date, checkbox or list.');
return request;

copy_card.beforeRequest:
var keep = inputs.keep_from_source ? JSON.parse(inputs.keep_from_source) : null;
request.query.keepFromSource = keep ? keep.join(',') : '';
return request;

list_card_activity.beforeRequest:
var page = inputs.page;
if (page !== undefined && page !== '') {
  var number = Number(page);
  if (!Number.isInteger(number) || number < 0 || number > 19) throw new Error('Page must be a whole number between 0 and 19.');
  request.query.page = String(number);
}
if (!request.query.filter) request.query.filter = 'updateCard';
return request;

add_card_attachment_from_url.beforeRequest:
if (!/^https?:\/\//i.test(inputs.url ?? '')) throw new Error('URL must start with http:// or https:// to be attached to a Trello card.');
if (inputs.set_cover === 'true') request.query.setCover = 'true';
return request;
